  const cardMesh = new THREE.Mesh(cardGeom, cardMat);
  group.add(cardMesh);

  // === CARD BORDER HAIRLINE (0.006 unit) ===
  const borderGeom = new THREE.PlaneGeometry(2.412, 3.212);
  geometries.push(borderGeom);
