  borderMesh.position.z = -0.001;
  group.add(borderMesh);

  // === HEADER STRIP (machined metal 2.4w x 0.08h) ===
  const headerGeom = new THREE.PlaneGeometry(2.4, 0.08);
  geometries.push(headerGeom);
  const headerMat = new THREE.MeshStandardMaterial({
    color: 0x16161d,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    anisotropicStrength: 0.6,
    side: THREE.DoubleSide
  });
  materials.push(headerMat);
  const headerMesh = new THREE.Mesh(headerGeom, headerMat);
  headerMesh.position.z = 0.01;
  headerMesh.position.y = 1.56; // 3.2 / 2 - 0.04
  group.add(headerMesh);

  // === TEXT CONTENT GROUP ===
  const textGroup = new THREE.Group();
  textGroup.position.z = 0.02;

  // Tier name: "ATELIER RESERVE"
  const tierNameMesh = TextUtils.createTextMesh(
    'ATELIER RESERVE',
    {
      family: config.typography['tier-name'].family || 'JetBrains Mono',
      fontSize: config.typography['tier-name'].fontSize || 20,
      fontWeight: config.typography['tier-name'].fontWeight || 700,
      letterSpacing: config.typography['tier-name'].letterSpacing || 0.08,
      lineHeight: config.typography['tier-name'].lineHeight || 1.2
    },
    0xe8ecf2
  );
  tierNameMesh.position.y = 1.21;
  tierNameMesh.position.x = -0.7;
  textGroup.add(tierNameMesh);

  // Price: "$480"
  const priceMesh = TextUtils.createTextMesh(
    '$480',
    {
      family: config.typography['price'].family || 'Lora',
      fontSize: config.typography['price'].fontSize || 62,
      fontWeight: config.typography['price'].fontWeight || 600,
      letterSpacing: config.typography['price'].letterSpacing || -0.01,
      lineHeight: config.typography['price'].lineHeight || 1
    },
    0xe8ecf2
  );
  priceMesh.position.y = 0.61;
  priceMesh.position.x = -0.7;
  textGroup.add(priceMesh);

  // Caption: "PER MONTH, BILLED ANNUALLY"
  const captionMesh = TextUtils.createTextMesh(
    'PER MONTH, BILLED ANNUALLY',
    {
      family: config.typography['caption'].family || 'JetBrains Mono',
      fontSize: config.typography['caption'].fontSize || 9,
      fontWeight: config.typography['caption'].fontWeight || 400,
      letterSpacing: config.typography['caption'].letterSpacing || 0.12,
      lineHeight: config.typography['caption'].lineHeight || 1.4
    },
    0x999999
  );
  captionMesh.position.y = 0.36;
  captionMesh.position.x = -0.7;
  textGroup.add(captionMesh);

  // Feature rows (4x, each 0.375h with 0.006-unit hairlines)
  const features = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing'
  ];

