  const featureMeshes = [];
  const featureHairlines = [];

  features.forEach((text, idx) => {
    const featureMesh = TextUtils.createTextMesh(
      text,
      {
        family: config.typography['feature'].family || 'JetBrains Mono',
        fontSize: config.typography['feature'].fontSize || 13,
        fontWeight: config.typography['feature'].fontWeight || 400,
        letterSpacing: config.typography['feature'].letterSpacing || 0,
        lineHeight: config.typography['feature'].lineHeight || 1.5
      },
      0xe8ecf2
    );
    featureMesh.position.y = featureY;
    featureMesh.position.x = -0.7;
    featureMesh.userData.origY = featureY;
    featureMesh.userData.staggerIndex = idx;
    featureMeshes.push(featureMesh);
    textGroup.add(featureMesh);

    // Hairline separator (0.006h)
    if (idx < features.length - 1) {
      const hairlineGeom = new THREE.PlaneGeometry(2.4, 0.006);
      geometries.push(hairlineGeom);
      const hairlineMat = new THREE.MeshBasicMaterial({
        color: 0x23232b,
        side: THREE.DoubleSide
      });
      materials.push(hairlineMat);
      const hairlineMesh = new THREE.Mesh(hairlineGeom, hairlineMat);
      hairlineMesh.position.z = 0.015;
      hairlineMesh.position.y = featureY - 0.1875; // Mid-gap between features
      textGroup.add(hairlineMesh);
      featureHairlines.push(hairlineMesh);
    }

    featureY -= 0.381; // 0.375 feature height + 0.006 hairline
  });

  group.add(textGroup);

  // === CTA BUTTON (1.4w x 0.36h) ===
  const ctaGeom = new THREE.PlaneGeometry(1.4, 0.36);
  geometries.push(ctaGeom);
  const ctaMat = createCTAMaterial();
  materials.push(ctaMat);
  const ctaMesh = new THREE.Mesh(ctaGeom, ctaMat);
  ctaMesh.position.y = -1.32; // -3.2 / 2 + 0.5 + 0.18
  ctaMesh.position.z = 0.02;
  ctaMesh.userData.isButton = true;
  textGroup.add(ctaMesh);

  // CTA Label: "JOIN THE RESERVE"
  const ctaLabelMesh = TextUtils.createTextMesh(
    'JOIN THE RESERVE',
    {
      family: config.typography['cta-label'].family || 'JetBrains Mono',
      fontSize: config.typography['cta-label'].fontSize || 13,
      fontWeight: config.typography['cta-label'].fontWeight || 700,
      letterSpacing: config.typography['cta-label'].letterSpacing || 0.08,
      lineHeight: config.typography['cta-label'].lineHeight || 1
    },
    0x16161d
  );
  ctaLabelMesh.position.y = -1.32;
  ctaLabelMesh.position.z = 0.03;
  textGroup.add(ctaLabelMesh);

