  // Card mount: weighted-settle (scale 1.04 -> 1.0 over 900ms)
  group.scale.set(1.04, 1.04, 1.04);
  const mountTl = gsap.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    overwrite: 'auto'
  });
  timelines.push(mountTl);

  // Feature rows: staggered fade-up (opacity 0->1, y +0.2->0 at 80ms stagger)
  const featureTl = gsap.timeline();
  featureMeshes.forEach((mesh) => {
    const staggerIdx = mesh.userData.staggerIndex;
    const origY = mesh.userData.origY;

    // Animate position
    featureTl.fromTo(
      mesh.position,
      { y: origY + 0.2 },
      {
        y: origY,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        overwrite: 'auto'
      },
      staggerIdx * 0.08
    );

    // Animate opacity
    if (mesh.material && typeof mesh.material.opacity !== 'undefined') {
      mesh.material.transparent = true;
      featureTl.fromTo(
        mesh.material,
        { opacity: 0 },
        {
          opacity: 1,
          duration: 0.5,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          overwrite: 'auto'
        },
        staggerIdx * 0.08
      );
    }
  });
  timelines.push(featureTl);

  // CTA press effect (scale 1.0 -> 0.97 over 120ms, yoyo)
  group.userData.handlers.ctaPress = () => {
    gsap.to(ctaMesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      yoyo: true,
      repeat: 1,
      overwrite: 'auto'
    });
  };

  // === CLEANUP ===
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    materials.forEach((mat) => {
      mat.dispose();
    });
    geometries.forEach((geom) => {
      geom.dispose();
    });
  };

  return group;
}

/**
 * Create CTA button material with engineered gradient
 * #ff4450 (at 0.0) -> #c1121f (at 1.0) with emissive #ff2a38 at 1.5x intensity
 */
function createCTAMaterial() {
  // Normalize local Y position (-0.18 to 0.18) to gradient space (0 to 1)
  const uvY = TSL.positionLocal.y.add(0.18).mul(2.777);

  // Color stops
  const colorTop = TSL.vec3(1.0, 0.267, 0.314); // #ff4450
  const colorBottom = TSL.vec3(0.757, 0.071, 0.122); // #c1121f
  const gradientColor = TSL.mix(colorTop, colorBottom, uvY);

  // Emissive
  const emissiveColor = TSL.vec3(1.0, 0.165, 0.220).mul(1.5); // #ff2a38 * 1.5

  const material = new THREE.MeshBasicMaterial({
    side: THREE.DoubleSide,
    transparent: true
  });

  material.colorNode = gradientColor;
  material.emissiveNode = emissiveColor;

  return material;
}
